{
  "decisions": {
    "P0078F0005": {
      "action": "repair",
      "representative_fact_id": "",
      "corrections": [
        {
          "statement": "표(p78:e616)에서 No-Pin의 평균 처리 속도는 약 13초 빠름(CPU 캐시 복사 이득), Pinned Memory는 약간 느림(DMA 셋업 오버헤드)으로 제시되었다.",
          "limits": "표의 셀 값으로 제시된 비교 항목이다. '약 13초 빠름'은 상대적 비교 표현이며 절대 수치가 아니다. 이 표는 외부 조언/해석의 일부로 실측 결과로 확인되지는 않았다.",
          "kind": "result",
          "claim_status": "observed",
          "source_origin": "measurement_log",
          "conditions": ["표 비교 항목", "평균 처리 속도"],
          "observations": [
            "No-Pin 평균 처리 속도: 약 13초 빠름 (CPU 캐시 복사 이득)",
            "Pinned Memory 평균 처리 속도: 약간 느림 (DMA 셋업 오버헤드)"
          ],
          "parameters": [],
          "measurements": [],
          "element_ids": ["p78:e616"]
        }
      ],
      "reason": "승인 후보 없음. p78:e616 표에 평균 처리 속도 행이 존재하나 원 사실이 ai_advice/해석으로 귀속되어 있어 measurement_log/observed로 정정하고 표의 한계(상대적 비교 표현, 실측 미확인)를 보존함."
    },
    "P0078F0006": {
      "action": "duplicate",
      "representative_fact_id": "P0078R0F0021",
      "corrections": [],
      "reason": "승인 후보 P0078R0F0021에 표의 셀 값(8.8ms~11.6ms, 1.64ms), 조건, 측정, 한계가 모두 포함되어 있고 별도 정보·미해결 충돌 없으므로 중복으로 처리."
    },
    "P0078F0007": {
      "action": "duplicate",
      "representative_fact_id": "P0078R0F0022",
      "corrections": [],
      "reason": "승인 후보 P0078R0F0022에 표의 셀 값(118μs, 47μs), 조건, 측정, 한계가 모두 포함되어 있고 별도 정보·미해결 충돌 없으므로 중복으로 처리."
    },
    "P0078F0008": {
      "action": "repair",
      "representative_fact_id": "",
      "corrections": [
        {
          "statement": "p78:e617에 따르면, No-Pin은 평소 CPU 캐시 복사 이득으로 빠르지만 윈도우 OS의 가상 메모리 정리나 백그라운드 작업 개입 시 최대 11.6ms까지 스파이크가 발생할 수 있고(1ms 무선 통신 데드라인 파괴 가능성), Pinned Memory는 매번 DMA 셋업 비용(1~2 μs)을 치러 평균 시간은 손해이나 OS 페이징을 차단하여 1.64ms를 넘지 않는 안정성을 제공한다고 설명되었다.",
          "limits": "이 설명은 p78:e617의 목록 형태 서술이며 외부 조언/해석의 일부로 실측 결과로 확인되지는 않았다. '절대적인 안정성', '결정론적 성능'은 실측 증명이 없는 해석적·규범적 주장이다. DMA 셋업 비용(1~2 μs)의 측정 조건이 특정되지 않았다.",
          "kind": "result",
          "claim_status": "interpretation",
          "source_origin": "research_note",
          "conditions": ["No-Pin", "Pinned Memory", "윈도우 OS"],
          "observations": [
            "No-Pin: 평소 CPU 캐시빨로 빠르지만 OS 가상 메모리 정리/백그라운드 작업 시 최대 11.6ms 스파이크 가능 (1ms 무선 통신 데드라인 파괴 가능성)",
            "Pinned Memory: DMA 셋업 비용(1~2 μs) 부담으로 평균 시간 손해, OS 페이징 차단으로 1.64ms 이하 안정성 제공"
          ],
          "parameters": [],
          "measurements": [
            {
              "metric": "No-Pin 최대 스파이크(설명값)",
              "value": "11.6",
              "value_kind": "scalar",
              "unit": "ms",
              "condition": "No-Pin, 윈도우 OS 간섭, 표 제시값",
              "element_ids": ["p78:e617"]
            },
            {
              "metric": "Pinned Memory 최대 지연(설명값)",
              "value": "1.64",
              "value_kind": "scalar",
              "unit": "ms",
              "condition": "Pinned Memory, 표 제시값",
              "element_ids": ["p78:e617"]
            },
            {
              "metric": "DMA 셋업 비용(설명값)",
              "value": "1",
              "value_kind": "scalar",
              "unit": "μs",
              "condition": "Pinned Memory, 표 제시값, 측정 조건 미특정",
              "element_ids": ["p78:e617"]
            },
            {
              "metric": "DMA 셋업 비용(설명값)",
              "value": "2",
              "value_kind": "scalar",
              "unit": "μs",
              "condition": "Pinned Memory, 표 제시값, 측정 조건 미특정",
              "element_ids": ["p78:e617"]
            }
          ],
          "element_ids": ["p78:e617"]
        }
      ],
      "reason": "승인 후보 없음. p78:e617에 해당 설명이 존재하나 '절대적 안정성·결정론적 성능' 등 규범적 주장과 DMA 셋업 비용 측정 조건 미특정 문제가 있어 해석적 한계를 보존하며 정정."
    }
  }
}
